  function fillMisForm(r,local){if(!r)return;if(r.date&&q('tm_date'))q('tm_date').value=r.date;if(r.shift&&q('tm_shift'))q('tm_shift').value=r.shift;comboSet('tm_vehicle',r.vehicleId||'');comboSet('tm_operator',r.operatorId||'');if(q('tm_ref'))q('tm_ref').value=r.paperRef||'';if(q('tm_open_kmr'))q('tm_open_kmr').value=r.openingKmr??'';if(q('tm_close_kmr'))q('tm_close_kmr').value=r.closingKmr??'';if(q('tm_open_hmr'))q('tm_open_hmr').value=r.openingHmr??'';if(q('tm_close_hmr'))q('tm_close_hmr').value=r.closingHmr??'';if(q('tm_notes'))q('tm_notes').value=r.notes||'';T.misRows=Math.max(10,Math.min(30,(r.rows||[]).length||10));renderMisRows(r.rows||[]);wireKmrCalc();wireDriverMeterCalc();setMisLocked(r.status==='SUBMITTED'||r.status==='VOID');if(local&&q('tm_draft_state'))q('tm_draft_state').textContent='Local draft restored'}
  function renderMisSummary(s){const data=s?.rows||[],t=s?.totals||{};const cards=data.map(x=>`<div class="erp-machine-card"><div><b>${safe(x.label)}</b><small>${n(x.hrsRun)} Hrs</small></div><div><span>Trips</span><b>${n(x.totalTrips)}</b></div><div><span>Qty</span><b>${n(x.totalQty)} MT</b></div><div><span>MT/Hr</span><b>${x.productivity==null?'—':n(x.productivity)}</b></div></div>`).join('');const rows=data.map(x=>`<tr><td>${safe(x.label)}</td><td>${n(x.openingHmr)}</td><td>${n(x.closingHmr)}</td><td>${n(x.hrsRun)}</td><td>${n(x.romTrips)}</td><td>${n(x.romQty)}</td><td>${n(x.obTrips)}</td><td>${n(x.obQty)}</td><td>${n(x.totalTrips)}</td><td>${n(x.totalQty)}</td><td>${x.productivity==null?'—':n(x.productivity)}</td></tr>`).join('');html('tm_summary',`<div class="erp-kpi-row"><div><span>Total Trips</span><b>${n(t.totalTrips||0)}</b></div><div><span>Total Qty</span><b>${n(t.totalQty||0)} MT</b></div><div><span>Running Hrs</span><b>${n(t.hrsRun||0)}</b></div><div><span>Productivity</span><b>${t.productivity==null?'—':n(t.productivity)} MT/Hr</b></div></div><div class="erp-machine-grid">${cards||'<div class="note">Submit MIS reports to build machine productivity.</div>'}</div><details class="erp-full-report"><summary>View detailed excavator / loader report</summary><div class="table-wrap erp-compact-table-wrap"><table class="tiom-report-table"><thead><tr><th>Equipment / Machine</th><th>Start HMR</th><th>End HMR</th><th>Hrs</th><th>ROM Trips</th><th>ROM Qty</th><th>OB Trips</th><th>OB Qty</th><th>Total Trips</th><th>Total Qty</th><th>MT/Hr</th></tr></thead><tbody>${rows||'<tr><td colspan="11" class="note">No submitted MIS reports.</td></tr>'}</tbody></table></div></details>`)}

  function renderMisSummaryCompare(today,range){renderMisSummary(today);const a=q('tm_summary')?.innerHTML||'';renderMisSummary(range);const b=q('tm_summary')?.innerHTML||'';const tl=(today?.fromDate||T.mis?.date||'')+' · Shift '+(today?.shift||T.mis?.shift||'');const rl=(range?.fromDate||'')+' → '+(range?.toDate||'')+' · '+(range?.shift==='ALL'?'All shifts':'Shift '+(range?.shift||''));html('tm_summary','<div class="prod-period-title"><b>TODAY / SELECTED SHIFT</b><span>'+safe(tl)+'</span></div>'+a+'<div class="prod-period-title cumulative"><b>CUMULATIVE RANGE</b><span>'+safe(rl)+'</span></div>'+b)}
  window.loadMisProductivity=function(){const from=v('tm_prod_from'),to=v('tm_prod_to'),reportShift=v('tm_prod_shift')||'ALL';appRun(function(d){if(!T.mis)return;T.mis.summaryRange=d.summaryRange;T.mis.reportFrom=d.reportFrom;T.mis.reportTo=d.reportTo;T.mis.reportShift=d.reportShift;renderMisSummaryCompare(T.mis.summaryToday||T.mis.summary,d.summaryRange)},function(e){toast(e.message,true)}).getTiomMisDesk({date:v('tm_date')||S.boot.today,shift:v('tm_shift')||S.boot.shift,reportFrom:from,reportTo:to,reportShift})};

