  function drillingCalc(i){const d=Number(v('dr_dc_'+i))-Number(v('dr_do_'+i)),c=Number(v('dr_cc_'+i))-Number(v('dr_co_'+i)),m=Number(v('dr_rom_'+i)||0)+Number(v('dr_bhj_'+i)||0);if(q('dr_drun_'+i))q('dr_drun_'+i).textContent=Number.isFinite(d)&&d>=0?n(d):'—';if(q('dr_crun_'+i))q('dr_crun_'+i).textContent=Number.isFinite(c)&&c>=0?n(c):'—';if(q('dr_total_'+i))q('dr_total_'+i).textContent=n(m);if(q('dr_mph_'+i))q('dr_mph_'+i).textContent=Number.isFinite(d)&&d>0?n(m/d):'—'}
  function renderDrillingSummaryBlock(summary,title){const t=summary?.totals||{},rows=(summary?.rows||[]).map(x=>`<tr><td>${safe(x.label)}</td><td>${n(x.drillHours)}</td><td>${n(x.compressorHours)}</td><td>${n(x.holes)}</td><td>${n(x.romObMeterage)}</td><td>${n(x.bhjBhqMeterage)}</td><td>${n(x.totalMeterage)}</td><td>${x.meterPerHour==null?'—':n(x.meterPerHour)}</td><td>${n(x.hsdLitres)}</td><td>${x.litrePerMeter==null?'—':n(x.litrePerMeter)}</td><td>${n(x.breakdownHours)}</td></tr>`).join('')||'<tr><td colspan="11" class="note">No drilling data.</td></tr>';return `<div class="prod-period-title"><b>${safe(title)}</b><span>${safe(summary?.fromDate||'')} → ${safe(summary?.toDate||'')} · ${summary?.shift==='ALL'?'All shifts':'Shift '+safe(summary?.shift||'')}</span></div><div class="erp-kpi-row"><div><span>Holes</span><b>${n(t.holes)}</b></div><div><span>Total Meterage</span><b>${n(t.totalMeterage)} m</b></div><div><span>Meter / Hr</span><b>${t.meterPerHour==null?'—':n(t.meterPerHour)}</b></div><div><span>HSD</span><b>${n(t.hsdLitres)} L</b></div><div><span>BD Hours</span><b>${n(t.breakdownHours)}</b></div></div><div class="table-wrap erp-compact-table-wrap"><table class="tiom-report-table wide"><thead><tr><th>Drill Set</th><th>Drill Hrs</th><th>Comp Hrs</th><th>Holes</th><th>ROM/OB m</th><th>BHJ/BHQ m</th><th>Total m</th><th>m/Hr</th><th>HSD L</th><th>L/m</th><th>BD Hr</th></tr></thead><tbody>${rows}</tbody></table></div>`}
  function renderDrillingDesk(){const d=T.drill||{},rows=d.rows||[];if(!rows.length){html('dr_body','<div class="panel note"><b>No Drill Set Master configured.</b> Open Masters → Drill Sets and pair each drill machine with its compressor.</div>');return}const body=rows.map((r,i)=>`<tr><td>${safe(r.label)}</td><td>${combo('dr_src_'+i,d.sourceLocations||[],r.sourceLocationId,'','Source / Face')}</td><td><input id="dr_do_${i}" type="number" step="0.01" value="${r.drillOpenHmr??''}" oninput="drillingCalc(${i})"></td><td><input id="dr_dc_${i}" type="number" step="0.01" value="${r.drillCloseHmr??''}" oninput="drillingCalc(${i})"></td><td id="dr_drun_${i}">—</td><td><input id="dr_co_${i}" type="number" step="0.01" value="${r.compressorOpenHmr??''}" oninput="drillingCalc(${i})"></td><td><input id="dr_cc_${i}" type="number" step="0.01" value="${r.compressorCloseHmr??''}" oninput="drillingCalc(${i})"></td><td id="dr_crun_${i}">—</td><td><input id="dr_holes_${i}" type="number" step="1" min="0" value="${r.holes??0}"></td><td><input id="dr_rom_${i}" type="number" step="0.01" min="0" value="${r.romObMeterage??0}" oninput="drillingCalc(${i})"></td><td><input id="dr_bhj_${i}" type="number" step="0.01" min="0" value="${r.bhjBhqMeterage??0}" oninput="drillingCalc(${i})"></td><td id="dr_total_${i}">—</td><td id="dr_mph_${i}">—</td><td><input id="dr_bd_${i}" type="number" step="0.01" min="0" value="${r.breakdownHours??''}"></td><td><input id="dr_note_${i}" value="${safe(r.remarks||'')}" placeholder="Remark"></td></tr>`).join('');html('dr_body',`<div class="panel tiom-sap-card"><div class="tiom-card-title"><div><b>DRILLING SHIFT ENTRY</b><span>One Drill Set = Drill HMR + Compressor HMR. HSD is pulled from central HSD issues.</span></div><button class="btn primary tiny" onclick="saveDrilling()">Save Drilling</button></div><div class="table-wrap tiom-trip-scroll"><table class="tiom-entry-table wide"><thead><tr><th>Drill Set</th><th>Source</th><th>Drill Open</th><th>Drill Close</th><th>Drill Hrs</th><th>Comp Open</th><th>Comp Close</th><th>Comp Hrs</th><th>Holes</th><th>ROM/OB m</th><th>BHJ/BHQ m</th><th>Total m</th><th>m/Hr</th><th>BD Hr</th><th>Remarks</th></tr></thead><tbody>${body}</tbody></table></div></div><div class="panel tiom-sap-card"><div class="tiom-card-title"><b>DRILLING PRODUCTIVITY REPORT</b><span>Today + cumulative selected range</span></div>${renderDrillingSummaryBlock(d.summaryToday,'TODAY / SELECTED SHIFT')}${renderDrillingSummaryBlock(d.summaryRange,'CUMULATIVE RANGE')}</div>`);rows.forEach((_,i)=>drillingCalc(i))}
  function collectDrilling(){return (T.drill?.rows||[]).map((r,i)=>({drillSetId:r.drillSetId,sourceLocationId:v('dr_src_'+i),drillOpenHmr:v('dr_do_'+i),drillCloseHmr:v('dr_dc_'+i),compressorOpenHmr:v('dr_co_'+i),compressorCloseHmr:v('dr_cc_'+i),holes:v('dr_holes_'+i),romObMeterage:v('dr_rom_'+i),bhjBhqMeterage:v('dr_bhj_'+i),breakdownHours:v('dr_bd_'+i),remarks:v('dr_note_'+i)}))}
