  function renderSavedReports(){const d=T.mis||{},from=d.reportFrom||d.date||S.boot.today,to=d.reportTo||d.date||S.boot.today;html('tiom_prod_body',`<div class="tiom-mis-toolbar"><b>SAVED DRIVER SHIFT REPORTS</b><label>From<input id="ts_from" type="date" value="${safe(from)}"></label><label>To<input id="ts_to" type="date" value="${safe(to)}"></label><label>Shift<select id="ts_shift"><option value="ALL">All shifts</option>${shiftOpts(d.reportShift==='ALL'?'':d.reportShift)}</select></label><label>Search<input id="ts_search" placeholder="Date / truck / driver / ref / status" oninput="filterSavedReports()"></label><button class="btn primary small" onclick="loadSavedReports()">Load Range</button></div><div id="ts_body"><div class="loading">Loading saved reports…</div></div>`);loadSavedReports()}
  window.loadSavedReports=function(){const from=v('ts_from')||S.boot.today,to=v('ts_to')||S.boot.today,reportShift=v('ts_shift')||'ALL';appRun(function(d){T.mis=d;T.savedReports=d.reports||[];renderSavedTable(T.savedReports)},function(e){html('ts_body',`<div class="bad">${safe(e.message)}</div>`)}).getTiomMisDesk({date:to,shift:S.boot.shift,reportFrom:from,reportTo:to,reportShift})};
  function renderSavedTable(rows){const body=(rows||[]).map(x=>{const del=x.status==='DRAFT'?`<button class="btn danger tiny" onclick="removeMisReport('${safe(x.reportId)}','DRAFT')">Delete Draft</button>`:(S.boot.user.isManagement&&x.status==='SUBMITTED'?`<button class="btn danger tiny" onclick="removeMisReport('${safe(x.reportId)}','SUBMITTED')">Void</button>`:'');const h=(x.openingHmr!=null&&x.closingHmr!=null)?n(Number(x.closingHmr)-Number(x.openingHmr)):'—';return `<tr data-search="${safe((x.date+' '+x.shift+' '+x.vehicleId+' '+(x.paperRef||'')+' '+x.status+' '+(x.operatorId||'')).toLowerCase())}"><td>${safe(x.date)}</td><td>${safe(x.shift)}</td><td>${safe(x.vehicleId)}</td><td>${safe(x.operatorId||'—')}</td><td>${safe(x.paperRef||'—')}</td><td>${h}</td><td>${safe(x.status)}</td><td>${safe(x.enteredAt)}</td><td><button class="btn secondary tiny" onclick="editSavedReport('${safe(x.reportId)}')">${x.status==='DRAFT'?'Edit':'View'}</button>${del}</td></tr>`}).join('')||'<tr><td colspan="9" class="note">No saved reports in this date range.</td></tr>';html('ts_body',`<div class="panel tiom-sap-card"><div class="table-wrap"><table class="tiom-entry-table"><thead><tr><th>Date</th><th>Shift</th><th>Tripper</th><th>Driver</th><th>Report Ref</th><th>HMR Hrs</th><th>Status</th><th>Entered</th><th>Action</th></tr></thead><tbody id="ts_rows">${body}</tbody></table></div><div class="tiom-help">Date-range report. Submitted records remain in the audit trail; Management can VOID an incorrect submitted report instead of deleting history.</div></div>`)}
